import { memo, useCallback, useRef } from 'react';
import { Tooltip, TooltipRefProps } from 'react-tooltip';
import i18n from '~/shared/i18n/i18n';

type CommonTooltipProps = {
  content: React.ReactNode;
  buttonId: string;
};

export const CommonTooltip = memo(function CommonTooltip({ content, buttonId }: CommonTooltipProps) {
  const tooltipRef = useRef<TooltipRefProps>(null);

  const toggleTooltip = useCallback(() => {
    if (tooltipRef.current?.isOpen) {
      tooltipRef.current?.close();
      return;
    }
    tooltipRef.current?.open({
      anchorSelect: `#${buttonId}`,
      content: <>{content}</>,
      place: 'top-end',
    });
  }, [buttonId, content]);

  return (
    <div className="flex flex-row">
      <button type="button" className="btn help-btn ml-2 mt-4" id={buttonId} onTouchStart={toggleTooltip}>
        <span>{i18n.t('help')}</span>
      </button>
      <Tooltip
        ref={tooltipRef}
        className="tooltip-base"
        openEvents={{ click: true, mouseenter: true, focus: true, mouseover: true }}
      />
    </div>
  );
});

CommonTooltip.displayName = 'CommonTooltip';
