import { useCallback } from 'react';
import i18n from '~/shared/i18n/i18n';
import { overlay } from '~/shared/lib/overlay';
import { Dialog, DialogProps } from '~/shared/ui/dialogs/dialog';
import { ErrorWithResponse, useErrorMessage } from './use-error-message';

// DialogProps에서 필요한 속성만 Pick하고 일부 속성은 옵셔널하게 변경
export type ConfirmParams = Pick<
  DialogProps,
  'message' | 'title' | 'buttonLabel' | 'onConfirmClick' | 'onCancelClick'
> & {
  error: NonNullable<DialogProps['message']>; // message는 필수값으로
  buttonLabel?: string[]; // 기본값이 있으므로 옵셔널
};

export const useNetworkErrorDialog = () => {
  const { formatErrorMessage } = useErrorMessage();

  const openNetworkErrorDialog = useCallback(
    ({ message, title, buttonLabel = [i18n.t('confirm')], onConfirmClick, onCancelClick }: ConfirmParams) => {
      const errorMessage = formatErrorMessage(message as ErrorWithResponse);
      overlay.exclusiveOpen(({ isOpen, close, unmount }) => (
        <Dialog
          open={isOpen}
          afterLeave={unmount}
          onClose={close}
          message={errorMessage}
          title={title}
          buttonLabel={buttonLabel}
          onConfirmClick={() => {
            close();
            onConfirmClick?.();
          }}
          onCancelClick={() => {
            close();
            onCancelClick?.();
          }}
        />
      ));
    },
    [],
  );

  return { openNetworkErrorDialog };
};
