import { useCallback } from 'react';
import { UseFormSetValue, useFormContext } from 'react-hook-form';
import { TempUserParams } from '~/entities/user/api/dtos/types';
import { SuperAppData } from '~/shared/api/dtos/enums';
import { generateSuperAppData } from '~/shared/lib/utils/generate-super-app-data';
import { SELECTED_USER_KEY } from '~/super-app-sample/model/constants';
import type { FormValues } from '~/super-app-sample/model/schema';

export const useGenerateUserData = (setValue: UseFormSetValue<FormValues>) => {
  const { clearErrors } = useFormContext();

  const generateNewUserData = useCallback(
    (cstrList: TempUserParams[]) => {
      localStorage.removeItem(SELECTED_USER_KEY);
      try {
        setValue('userCI', generateSuperAppData(SuperAppData.CI, cstrList));
        setValue('userId', generateSuperAppData(SuperAppData.통합아이디, cstrList));
        setValue('account', generateSuperAppData(SuperAppData.계좌번호, cstrList));
      } catch (error) {
        setValue('userCI', generateSuperAppData(SuperAppData.CI, []));
        setValue('userId', generateSuperAppData(SuperAppData.통합아이디, []));
        setValue('account', generateSuperAppData(SuperAppData.계좌번호, []));
      }
    },
    [setValue],
  );

  const updateExistingUserData = useCallback(
    (selectedUser: TempUserParams, selectionValue: string) => {
      clearErrors();
      setValue('userCI', selectedUser.ci || '');
      setValue('userId', selectedUser.cstmrNo || '');
      setValue('account', selectedUser.acnutno || '');
      localStorage.setItem(SELECTED_USER_KEY, selectionValue);
    },
    [setValue, clearErrors],
  );

  return {
    generateNewUserData,
    updateExistingUserData,
  };
};
