import { useEffect, useCallback } from 'react';
import { useImmer } from 'use-immer';
import type { SuperAppEncData } from '~/entities/super-app/model/types';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { TempUserParams } from '~/entities/user/api/dtos/types';
import { useGetCstmrListQuery } from '~/entities/user/api/use-get-cstmr-list-query';
import { SuperAppCommandOutbound, SuperAppData } from '~/shared/api/dtos/enums';
import { useNetworkErrorDialog } from '~/shared/lib/hooks/error/use-network-error-dialog';
import { devNotiBar } from '~/shared/lib/toast';
import { generateSuperAppData } from '~/shared/lib/utils/generate-super-app-data';
import { RsaOaep } from '~/shared/lib/utils/rsa-oaep';
import { PATHS } from '~/shared/routes/paths';
import { useSuperAppSampleForm } from './use-super-app-sample-form';
import { useSuperAppSampleHandler } from './use-super-app-sample-handler';
import { SELECTED_USER_KEY, NEW_USER } from '~/super-app-sample/model/constants';
import { buildUserSelectionValue, findUserBySelectionValue } from '~/super-app-sample/model/user-selection';

export const useSuperAppSamplePage = () => {
  const { openNetworkErrorDialog } = useNetworkErrorDialog();
  const { form, handleSubmit, resetUserInfo, clearSuperAppData } = useSuperAppSampleForm();
  const { setValue, reset, clearErrors, watch } = form;
  const { decryptText } = RsaOaep();
  const { data: cstrList, isPending } = useGetCstmrListQuery();
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const [labels, setLabels] = useImmer<string[]>([]);
  const [values, setValues] = useImmer<string[]>([]);
  const { handleSuperAppCommand } = useSuperAppSampleHandler();

  const initializeUserData = useCallback(async () => {
    clearSuperAppData();
    resetUserInfo();

    if (!cstrList) return [];

    const filterData = cstrList.filter((item) => !!item.ci);
    setLabels(['신규 사용자 생성', ...filterData.map((item) => item.koreanNm! + ':' + item.cstmrNo!)]);
    setValues([NEW_USER, ...filterData.map(buildUserSelectionValue)]);

    return filterData;
  }, [cstrList, setLabels, setValues, clearSuperAppData, resetUserInfo]);

  const restoreSelectedUser = useCallback(
    (filterData: TempUserParams[]) => {
      const savedSelectionValue = localStorage.getItem(SELECTED_USER_KEY);
      if (savedSelectionValue) {
        const selectedUser = findUserBySelectionValue(filterData, savedSelectionValue);
        if (selectedUser) {
          setTimeout(() => {
            setValue('selectCi', savedSelectionValue);
          }, 0);
        }
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [setValue],
  );

  const generateNewUserData = useCallback(() => {
    localStorage.removeItem(SELECTED_USER_KEY);
    try {
      setValue('userCI', generateSuperAppData(SuperAppData.CI, cstrList || []));
      setValue('userId', generateSuperAppData(SuperAppData.통합아이디, cstrList || []));
      setValue('account', generateSuperAppData(SuperAppData.계좌번호, cstrList || []));
    } catch (error) {
      setValue('userCI', generateSuperAppData(SuperAppData.CI, []));
      setValue('userId', generateSuperAppData(SuperAppData.통합아이디, []));
      setValue('account', generateSuperAppData(SuperAppData.계좌번호, []));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cstrList, setValue]);

  const updateExistingUserData = useCallback(
    (selectedUser: TempUserParams, selectionValue: string) => {
      setValue('userCI', selectedUser.ci || '');
      setValue('userId', selectedUser.cstmrNo || '');
      //console.log('superAppSample userId', selectedUser.cstmrNo);
      setValue('account', selectedUser.acnutno || '');
      localStorage.setItem(SELECTED_USER_KEY, selectionValue);
    },
    [setValue],
  );

  useEffect(() => {
    const initialize = async () => {
      const filterData = await initializeUserData();
      if (filterData) {
        restoreSelectedUser(filterData);
      }
    };

    initialize();
  }, [initializeUserData, restoreSelectedUser]);

  useEffect(() => {
    const subscription = watch((value, { name }) => {
      if (name === 'selectCi') {
        const selectionValue = value.selectCi;
        if (selectionValue === NEW_USER) {
          generateNewUserData();
        } else if (selectionValue && cstrList) {
          const selectedUser = findUserBySelectionValue(cstrList, selectionValue);
          if (selectedUser) {
            updateExistingUserData(selectedUser, selectionValue);
          }
        }
      }
    });
    return () => subscription.unsubscribe();
  }, [cstrList, generateNewUserData, updateExistingUserData, watch]);

  const processOutboundCommand = useCallback(async () => {
    if (!state?.encData) return;

    //console.log(`SuperApp 아웃바운드 명령 처리 ->  ${window.location.href}`);
    try {
      const decryptedData = await decryptText(state);
      if (Object.values(SuperAppCommandOutbound).includes(decryptedData.command as SuperAppCommandOutbound)) {
        await handleSuperAppCommand(decryptedData);
        await devNotiBar(`슈퍼앱 콜백 처리 -> ${decryptedData.command}`, 0, 2000);
      }
    } catch (error: any) {
      openNetworkErrorDialog({
        error: error,
        onConfirmClick: () => {
          window.location.replace(PATHS.superAppSample);
        },
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state?.encData]);

  useEffect(() => {
    processOutboundCommand();
  }, [processOutboundCommand]);

  const handlePageReset = () => {
    reset();
    clearErrors();
    setValue('selectCi', NEW_USER);
    generateNewUserData();
  };

  return {
    form,
    handleSubmit,
    handlePageReset,
    isPending,
    labels,
    values,
    cstrList,
  };
};
