import { zodResolver } from '@hookform/resolvers/zod';
import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';
import { SuperAppCommandInbound } from '~/shared/api/dtos/enums';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { devSnackBar } from '~/shared/lib/toast';
import { generateUrl } from '~/shared/lib/utils/generate-url';
import { RsaOaep } from '~/shared/lib/utils/rsa-oaep';
import { PATHS } from '~/shared/routes/paths';
import { formSchema, FormValues } from '~/super-app-sample/model/schema';

export const useSuperAppSampleForm = () => {
  const { openAlertDialog } = useAlertDialog();
  const [resetAuth, clearSuperAppData] = useStore(
    useShallow((s) => [s.authSlice.resetAuth, s.superAppSlice.clearSuperAppData]),
  );
  const { navigate } = useNavigate();
  const { encryptText } = RsaOaep();

  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    mode: 'all',
    defaultValues: {
      command: SuperAppCommandInbound.로그인,
      superAppCallback: window.location.origin + PATHS.superAppSample,
    },
  });

  useEffect(() => {
    const subscription = form.watch((value, { name }) => {
      if (name === 'command') {
        form.setValue('txCode', '');
      }
    });
    return () => subscription.unsubscribe();
  }, [form]);

  const handleReset = () => {
    form.reset();
    clearSuperAppData();
    resetAuth();
  };

  const handleSubmit = async (data: FormValues) => {
    try {
      //console.log('superAppSample submit ===> data', data);
      const encryptedData = await encryptText({
        ...data,
        ci: data.userCI,
        cstmrNo: data.userId,
        acnutno: data.account,
      });

      //console.log('superAppSample submit ===> encryptedData', encryptedData);
      await devSnackBar('전자지갑 앱으로 이동합니다', 3000, 1000);
      navigate(
        generateUrl({
          baseUrl: PATHS.intro,
          command: data.command,
          encData: encryptedData.encData,
          signature: encryptedData.signature,
          superAppCallback: data.superAppCallback,
        }),
        { replace: true },
      );
    } catch (error) {
      openAlertDialog({
        message: { error },
        onConfirmClick: () => {
          window.location.replace(PATHS.superAppSample);
        },
      });
    }
  };

  return {
    form,
    handleSubmit,
    resetUserInfo: resetAuth,
    clearSuperAppData,
    handleReset,
  };
};
