import { useSuspenseQuery } from '@tanstack/react-query';
import axios from 'axios';
import { GetCstmrListResponse } from '~/entities/user/api/dtos/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { queries } from '~/shared/api/query-keys';
import { resultify } from '~/shared/lib/utils/resultify';

export const getCstmrList = () => {
  return resultify(axios.post<GetCstmrListResponse>(`${API_URLS.tempReadList}`));
};

export const useGetCstmrListQuery = (options?: QueryOptions<GetCstmrListResponse, CBDCAxiosError>) => {
  return useSuspenseQuery<GetCstmrListResponse, CBDCAxiosError>({
    queryKey: queries.cstr.cstmrList.queryKey,
    queryFn: () => getCstmrList(),
    gcTime: 0,
    staleTime: 0,
    refetchOnMount: 'always',
    refetchOnWindowFocus: 'always',
    refetchOnReconnect: 'always',
    ...options,
  });
};
