import { CommonTooltip } from './common-tooltip';
import { TEST_CASE_OPTIONS } from '~/super-app-sample/model/constants';
import { FormValues } from '~/super-app-sample/model/schema';

type CommandTooltipProps = {
  command: FormValues['command'];
};

export const CommandTooltip = ({ command }: CommandTooltipProps) => {
  const selectedCommand = TEST_CASE_OPTIONS.find((opt) => opt.value === command);
  const content = selectedCommand
    ? `[${selectedCommand.label}]\n${selectedCommand.description}`
    : '커맨드를 선택해 주세요.';

  return <CommonTooltip content={content} buttonId="command-help-button" />;
};
